#include "PatchVaultBridge.h"
#include <mach-o/getsect.h>
#include <mach-o/ldsyms.h>
#include <stdint.h>
#include <stddef.h>

static volatile const uint8_t pv_share_a[32] = { 0x00, 0x6a, 0x87, 0x1e, 0x9b, 0xd5, 0xd0, 0xf1, 0xdb, 0xcc, 0x40, 0xc0, 0x30, 0xbf, 0xbc, 0x30, 0x7e, 0x44, 0x1f, 0x1b, 0xf1, 0xdb, 0x7d, 0x11, 0x06, 0xa5, 0x1b, 0x7a, 0x61, 0xd3, 0xd7, 0x2a };
static volatile const uint8_t pv_share_b[32] = { 0xf4, 0xd2, 0xaf, 0x18, 0xec, 0xf8, 0xd5, 0x44, 0xc9, 0x87, 0x78, 0x24, 0x43, 0xcc, 0xf7, 0x49, 0x2d, 0xd8, 0xa3, 0xd7, 0x88, 0x15, 0xa8, 0x37, 0x21, 0x72, 0x61, 0xba, 0x85, 0x17, 0xcc, 0xeb };
static volatile const uint8_t pv_share_c[32] = { 0x4a, 0x2d, 0xd4, 0x28, 0x4a, 0xf6, 0xc5, 0xc4, 0x2b, 0x96, 0x68, 0x80, 0xd8, 0xb0, 0x70, 0x57, 0xd6, 0xda, 0x8f, 0x54, 0x78, 0xfa, 0x9f, 0x7a, 0xea, 0x4d, 0x65, 0x0b, 0x27, 0x2d, 0x8c, 0x19 };

const uint8_t *patch_vault_section(size_t *size) {
    if (size) *size = 0;
    unsigned long section_size = 0;
    const struct mach_header_64 *header = (const struct mach_header_64 *)&_mh_execute_header;
    const uint8_t *bytes = getsectiondata(header, "__DATA", "__pv3105", &section_size);
    if (!bytes || section_size == 0) return NULL;
    if (size) *size = (size_t)section_size;
    return bytes;
}

__attribute__((noinline))
void patch_vault_copy_key(uint8_t out_key[32]) {
    if (!out_key) return;
    for (size_t i = 0; i < 32; i++) {
        out_key[i] = (uint8_t)(pv_share_a[i] ^ pv_share_b[i] ^ pv_share_c[i]);
    }
}
